pm.test("Validar que la respuesta sea 200", function () {
    pm.response.to.have.status(200);
});
pm.test("Tiempo de respuesta menor a 3500ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(3500);
});
pm.test("La respuesta contiene la lista de productos", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("products");
    pm.expect(jsonData.products.length).to.be.above(0);
});

const jsonData = pm.response.json();

pm.test("El código interno de respuesta es 200", function () {
    pm.expect(jsonData.responseCode).to.eql(200);
});

pm.test("Devuelve al menos un producto coincidente", function () {
    pm.expect(jsonData.products).to.be.an("array").that.is.not.empty;
});

pm.test("Todos los productos coinciden en nombre o categoría con el término buscado", function () {
    jsonData.products.forEach((producto) => {
        const enNombre = producto.name.toLowerCase().includes("top");
        const enCategoria = producto.category && producto.category.category.toLowerCase().includes("top");
        pm.expect(enNombre || enCategoria).to.be.true;
    });
});

const jsonData = pm.response.json();

pm.test("Devuelve responseCode 400 por parámetro faltante", function () {
    pm.expect(jsonData.responseCode).to.eql(400);
});

pm.test("El mensaje de error indica el parámetro requerido", function () {
    pm.expect(jsonData.message).to.eql("Bad request, search_product parameter is missing in POST request.");
});

const jsonData = pm.response.json();

pm.test("Devuelve responseCode 404 para usuario inexistente", function () {
    pm.expect(jsonData.responseCode).to.eql(404);
});

pm.test("Muestra el mensaje de usuario no encontrado", function () {
    pm.expect(jsonData.message).to.eql("User not found!");
});

const jsonData = pm.response.json();

pm.test("Bloquea métodos no permitidos con responseCode 405", function () {
    pm.expect(jsonData.responseCode).to.eql(405);
    pm.expect(jsonData.message).to.eql("This request method is not supported.");
});
